struct BigObject {
    BigObject() = default;
    // Copy/Move operations are typically elided in these cases
    BigObject(const BigObject&) = delete; 
};

// --- Guaranteed Elision 1: Initialization from a temporary (C++17) ---
BigObject make_object() {
    return BigObject{}; // Prvalue return
}

void scope1() {
    BigObject a = make_object(); // Guaranteed elision of copy/move
}

// --- Guaranteed Elision 2: Prvalue return (C++17) ---
BigObject factory() {
    return BigObject(); // Direct construction into return slot
}

// --- Scenario NOT Guaranteed (Named Return Value) ---
BigObject complex_factory(bool condition) {
    BigObject result;
    if (condition) {
        // NRVO likely happens, but is NOT mandated by standard
        return result; 
    }
    return result; 
}

// --- Defeating NRVO via explicit move ---
BigObject move_factory() {
    BigObject local;
    // Explicitly forces a move construction instead of relying on NRVO/Elision
    return std::move(local); 
}
